# save transform generalized based on demo findings
src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v]
        if len(nz) >= 2 and nz[-1] - nz[0] >= 4:
            gaps = [c for c in range(nz[0] + 1, nz[-1]) if row[c] == 0]
            if gaps:
                bars.append((r, row[nz[0]], gaps))
    # vertical colors change at each intersected horizontal bar; terminal color comes from short marker below.
    marker = {}
    for c in range(w):
        vals = [(r, grid[r][c]) for r in range(h) if grid[r][c] and all(grid[r][x] == 0 for x in range(w) if x != c)]
        if vals:
            marker[c] = vals[-1][1]
    cols = sorted(set(c for r, color, gaps in bars for c in gaps))
    for c in cols:
        hits = [(r, color) for r, color, gaps in bars if c in gaps]
        for i, (r, color) in enumerate(hits):
            top = 0 if i == 0 else hits[i-1][0] + 1
            bottom = hits[i+1][0] if i+1 < len(hits) else h
            for y in range(top, bottom):
                if grid[y][c] == 0: out[y][c] = color
            out[r][c] = color
        if c in marker:
            start = hits[-1][0] + 1
            for y in range(start, h):
                if grid[y][c] == 0: out[y][c] = marker[c]
    return out
'''
